import{_ as a,C as r,o as i,c as o,a4 as n,E as s}from"./chunks/framework.BybBnFXO.js";const b=JSON.parse('{"title":"Classification","description":"","frontmatter":{},"headers":[],"relativePath":"classification/intro.md","filePath":"classification/intro.md","lastUpdated":1785920831000}'),l={name:"classification/intro.md"};function d(c,t,h,m,p,u){const e=r("GemGallery");return i(),o("div",null,[t[0]||(t[0]=n('<h1 id="classification" tabindex="-1">Classification <a class="header-anchor" href="#classification" aria-label="Permalink to &quot;Classification&quot;">​</a></h1><blockquote><p><em>From mineral species to the gem we set in a ring.</em></p></blockquote><p>Every gemstone begins as a mineral — a naturally occurring, inorganic solid with a definite chemical composition and ordered atomic structure. Classification is the first step in understanding gemstones: where they come from, how they behave, and what makes each one unique.</p><h2 id="mineralogical-classification" tabindex="-1">Mineralogical Classification <a class="header-anchor" href="#mineralogical-classification" aria-label="Permalink to &quot;Mineralogical Classification&quot;">​</a></h2><p>The primary classification of gemstones follows mineral species, based on chemical composition and crystal structure.</p><table tabindex="0"><thead><tr><th>Material</th><th>Mineral Family</th><th>Representative Gems</th></tr></thead><tbody><tr><td><strong>Natural minerals</strong></td><td>Corundum</td><td>Ruby · Sapphire</td></tr><tr><td></td><td>Beryl</td><td>Emerald · Aquamarine · Morganite</td></tr><tr><td></td><td>Quartz</td><td>Amethyst · Citrine · Rock Crystal</td></tr><tr><td></td><td>Garnet</td><td>Tsavorite · Demantoid · Almandine</td></tr><tr><td></td><td>Tourmaline</td><td>Paraíba · Watermelon</td></tr><tr><td></td><td>Spinel</td><td>Red · Blue Spinel</td></tr><tr><td></td><td>Diamond</td><td>Colourless · Fancy colours</td></tr><tr><td></td><td>Feldspar</td><td>Moonstone · Labradorite · Amazonite</td></tr><tr><td></td><td>Zoisite</td><td>Tanzanite</td></tr><tr><td></td><td>Opal</td><td>Precious opal · Fire opal</td></tr><tr><td><strong>Organic materials</strong></td><td>Biogenic</td><td>Pearl · Amber · Coral</td></tr><tr><td><strong>Synthetic</strong></td><td>Lab-grown</td><td>Flux ruby · Hydrothermal emerald · CVD diamond</td></tr><tr><td></td><td>Simulants</td><td>Cubic zirconia · Glass · Moissanite</td></tr></tbody></table><blockquote><p><strong>→ 60 species</strong>, from Diamond to Chrysoprase. Browse the <a href="#all-60-gem-species">full list</a> below, or explore by <a href="./mineral-groups/intro.html">mineral group</a>, <a href="./crystal-systems/cubic.html">crystal system</a>, or <a href="./optical-phenomena/intro.html">optical phenomenon</a>.</p></blockquote><h2 id="traditional-classification" tabindex="-1">Traditional Classification <a class="header-anchor" href="#traditional-classification" aria-label="Permalink to &quot;Traditional Classification&quot;">​</a></h2><p>Historically, gems were divided into <strong>precious</strong> and <strong>semi-precious</strong> — a holdover from 19th-century European marketing rather than any scientific distinction.</p><table tabindex="0"><thead><tr><th>Traditional Category</th><th>Examples</th><th>Modern View</th></tr></thead><tbody><tr><td><strong>Precious</strong></td><td>Diamond, Ruby, Sapphire, Emerald</td><td>These four remain the most commercially significant, but modern gemology no longer uses this ranking.</td></tr><tr><td><strong>Semi-precious</strong></td><td>Everything else</td><td>Misleading — many &quot;semi-precious&quot; stones (Tsavorite, Paraíba Tourmaline, Alexandrite) are rarer and more valuable than &quot;precious&quot; stones.</td></tr></tbody></table><blockquote><p><strong>Modern gemology does not use the &quot;precious vs. semi-precious&quot; distinction.</strong> Scarcity, beauty, and durability are what determine a gem&#39;s value, not an inherited label.</p></blockquote><h2 id="classification-by-crystal-system" tabindex="-1">Classification by Crystal System <a class="header-anchor" href="#classification-by-crystal-system" aria-label="Permalink to &quot;Classification by Crystal System&quot;">​</a></h2><p>There are seven crystal systems (plus amorphous). Each gem crystallizes in one:</p><ul><li><strong>Cubic</strong> — Diamond, Spinel, Garnet</li><li><strong>Tetragonal</strong> — Zircon, Rutile</li><li><strong>Orthorhombic</strong> — Tanzanite, Alexandrite, Topaz</li><li><strong>Hexagonal</strong> — Beryl (Emerald, Aquamarine), Apatite</li><li><strong>Trigonal</strong> — Ruby, Sapphire, Quartz, Tourmaline</li><li><strong>Monoclinic</strong> — Orthoclase, Spodumene</li><li><strong>Triclinic</strong> — Kyanite, Turquoise</li><li><strong>Amorphous</strong> — Opal, Obsidian, Amber</li></ul><p><em>Begin with the <a href="./crystal-systems/cubic.html">cubic (isometric) system</a>.</em></p><h2 id="classification-by-mineral-group" tabindex="-1">Classification by Mineral Group <a class="header-anchor" href="#classification-by-mineral-group" aria-label="Permalink to &quot;Classification by Mineral Group&quot;">​</a></h2><p>For a chemistry-structured view, see <a href="./mineral-groups/intro.html"><strong>Mineral Groups</strong></a> — eight families covering native elements, oxides, three silicate subclasses, plus phosphates, carbonates, sulfides, and halides.</p><h2 id="classification-by-optical-phenomena" tabindex="-1">Classification by Optical Phenomena <a class="header-anchor" href="#classification-by-optical-phenomena" aria-label="Permalink to &quot;Classification by Optical Phenomena&quot;">​</a></h2><p>Beyond the catalog of phenomena below, see <a href="./optical-phenomena/intro.html"><strong>Optical Phenomena</strong></a> — detailed pages on six observable effects (star, cat&#39;s-eye, color change, moonstone sheen, labradorite schiller, sunstone glitter).</p><h2 id="classification-by-optical-phenomena-1" tabindex="-1">Classification by Optical Phenomena <a class="header-anchor" href="#classification-by-optical-phenomena-1" aria-label="Permalink to &quot;Classification by Optical Phenomena&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phenomenon</th><th>Description</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Asterism</strong></td><td>Star-shaped light reflection</td><td>Star Ruby, Star Sapphire</td></tr><tr><td><strong>Chatoyancy</strong></td><td>Cat&#39;s-eye band of light</td><td>Cat&#39;s-eye Chrysoberyl, Tiger&#39;s Eye</td></tr><tr><td><strong>Color Change</strong></td><td>Different colors under different light</td><td>Alexandrite, Color-change Sapphire</td></tr><tr><td><strong>Play of Color</strong></td><td>Rainbow spectral flash</td><td>Opal</td></tr><tr><td><strong>Iridescence</strong></td><td>Pearly or rainbow sheen</td><td>Moonstone, Labradorite</td></tr><tr><td><strong>Adularescence</strong></td><td>Blue-white floating glow</td><td>Moonstone</td></tr><tr><td><strong>Labradorescence</strong></td><td>Metallic schiller</td><td>Labradorite</td></tr><tr><td><strong>Aventurescence</strong></td><td>Sparkly metallic inclusions</td><td>Aventurine, Sunstone</td></tr></tbody></table><p>For the underlying <strong>physical causes of color</strong>, see <a href="./color-causes/intro.html"><strong>Color Cause</strong></a> — transition-metal ions, color centers, and charge transfer.</p><h2 id="classification-by-color" tabindex="-1">Classification by Color <a class="header-anchor" href="#classification-by-color" aria-label="Permalink to &quot;Classification by Color&quot;">​</a></h2><p>Gems are often classified by their primary color for practical identification:</p><table tabindex="0"><thead><tr><th>Color</th><th>Typical Gems</th></tr></thead><tbody><tr><td>Red</td><td>Ruby, Spinel, Garnet</td></tr><tr><td>Blue</td><td>Sapphire, Tanzanite, Topaz</td></tr><tr><td>Green</td><td>Emerald, Tsavorite, Peridot</td></tr><tr><td>Yellow</td><td>Citrine, Yellow Sapphire, Heliodor</td></tr><tr><td>Pink</td><td>Morganite, Pink Sapphire, Kunzite</td></tr><tr><td>Purple</td><td>Amethyst, Purple Sapphire</td></tr><tr><td>Colorless</td><td>Diamond, Zircon, Colorless Sapphire</td></tr></tbody></table><h2 id="how-gems-are-organized-in-gematlas" tabindex="-1">How gems are organized in GemAtlas <a class="header-anchor" href="#how-gems-are-organized-in-gematlas" aria-label="Permalink to &quot;How gems are organized in GemAtlas&quot;">​</a></h2><p>Each gem in this collection has a dedicated page with its physical properties, optical characteristics, treatments, and references. Browse the full list below, or use the sidebar to explore by mineral group, crystal system, or optical phenomenon.</p><h2 id="all-60-gem-species" tabindex="-1">All 60 Gem Species <a class="header-anchor" href="#all-60-gem-species" aria-label="Permalink to &quot;All 60 Gem Species&quot;">​</a></h2>',28)),s(e,{locale:"en"})])}const y=a(l,[["render",d]]);export{b as __pageData,y as default};
